import * as E from './engine.js';
export function operationsPanel(s,h){const {panelHead,esc,clock,fmt}=h,p=E.campaignProgress(s);return panelHead('ESCENARIOS DEL ARCHIVO ORIGINAL','Operaciones de Social Wars')+'<p>22 misiones de historia y un asedio semanal. Islas de 100 × 100, niebla de guerra y objetivos propios. Las tropas prestadas regresan al mando de la misión; las bajas de tu ejército son permanentes.</p><div class="action-row"><button data-action="frontier">Explorar islas procedurales</button><button data-action="campaign-section" data-type="legacy">12 escaramuzas Auralis</button></div><div class="mission-list">'+E.MISSIONS.map(m=>{const locked=E.missionLock(s,m.id),stars=p.stars[m.id]||0;return'<article class="mission-card"><div class="mission-number">'+(m.storyIndex<0?'S':String(m.storyIndex+1).padStart(2,'0'))+'</div><div><h3>'+esc(m.name)+'</h3><p>'+esc(m.objective)+'</p><small>Base '+m.hq+' · 100 × 100 · '+clock(m.limit)+' · '+(m.noAir?'sin aeronaves':'operación combinada')+'</small><span class="stars">'+'★'.repeat(stars)+'☆'.repeat(3-stars)+'</span>'+(locked?'<small>'+esc(locked)+'</small>':'')+'</div><button data-action="mission-preview" data-id="'+m.id+'" '+(locked?'disabled':'')+'>Preparar</button></article>';}).join('')+'</div><p class="tiny">Los rangos II y III refuerzan al enemigo. Cada rango concede su premio una sola vez; el asedio renueva el premio cada semana. Recuperar instalaciones puede desbloquear planos del catálogo original.</p>';}
export function missionBriefing(s,id,h){const {head,esc,clock}=h,m=E.MISSIONS.find(m=>m.id===id),p=E.campaignProgress(s),stars=p.stars[id]||0;return head('OPERACIÓN · 100 × 100',esc(m.name))+'<p>'+esc(m.objective)+'</p><p>Reconoce el terreno bajo la niebla, despliega tus reservas en las casillas azules y dirige al grupo con órdenes de movimiento o avance y ataque. Tienes '+clock(m.limit)+'.</p>'+(m.noAir?'<p class="warning">Las aeronaves permanecen en tu base durante esta misión.</p>':'')+(m.mode==='stealth'?'<p class="warning">Operación de un único agente: recibirás un especialista prestado. Tu ejército permanece a salvo en la base.</p>':'<p>Tu ejército aporta '+s.army.length+' tropas. El comandante de la misión es prestado. Los supervivientes y las reservas regresan al terminar.</p>')+'<div class="action-row">'+[1,2,3].map(rank=>'<button data-action="mission-start" data-id="'+id+'" data-index="'+rank+'" '+(rank>stars+1?'disabled':'')+'>Rango '+['I','II','III'][rank-1]+(stars>=rank?' · completado':'')+'</button>').join('')+'</div><p class="tiny">Preparar carga los datos y gráficos del escenario bajo demanda. Puedes retirarte con las reservas y los supervivientes.</p>';}
export function missionObjectives(s,h){const {head,esc,clock}=h,b=s.battle,m=b?.mission;if(!m)return'';const all=[...b.units,...b.buildings],ids=[...new Set([...(m.targets||[]),...(m.primary||[]),m.radio,m.intelligence,...b.units.filter(u=>u.capturable).map(u=>u.id)].filter(Boolean))],remaining=all.filter(u=>u.side==='enemy'&&u.hp>0).length;return head('OBJETIVOS DE LA OPERACIÓN',esc(b.name))+'<p>'+esc(m.objective)+'</p><div class="stat-row"><span>Tiempo disponible</span><strong>'+clock(b.limit-b.elapsed)+'</strong></div><div class="stat-row"><span>Defensores restantes</span><strong>'+remaining+'</strong></div>'+(m.mode==='escort'||m.mode==='rescue'?'<div class="stat-row"><span>Rescatados / evacuados</span><strong>'+m.rescued.length+' / 3</strong></div>':'')+(m.mode==='survive'?'<div class="stat-row"><span>Oleadas</span><strong>'+m.wave+' / 5</strong></div>':'')+(m.extraction?'<button class="wide" data-action="mission-focus" data-x="'+m.extraction.x+'" data-y="'+m.extraction.y+'">Localizar extracción</button>':'')+ids.map(id=>{const o=all.find(v=>v.id===id);if(!o)return'';const done=o.hp<=0||m.captured.includes(id)||m.rescued.includes(id),interact=o.interactable||o.capturable||o.id===m.intelligence;return'<article class="quest-card"><h3>'+esc(E.BUILDINGS[o.type]?.name||E.UNITS[o.type]?.name)+'</h3><p>'+(done?'Completado':o.invulnerable?'Protegido: completa primero el objetivo anterior.':'Posición '+Math.floor(o.x)+', '+Math.floor(o.y))+'</p><div class="action-row"><button data-action="mission-focus" data-x="'+o.x+'" data-y="'+o.y+'">Localizar</button>'+(interact&&!done?'<button data-action="mission-interact" data-id="'+id+'">Interactuar</button>':'')+'</div></article>';}).join('')+'<p class="tiny">Acerca tropas terrestres para capturar radios, transportes y rescatar aliados. Selecciona tropas junto a un barco para embarcar; selecciona el barco y marca una orilla para desembarcar.</p>';}
export function skillsPanel(s,selected,h){const {esc,clock}=h,b=s.battle;if(!b)return'';if(b.kind==='colony')return'<div class="skill-title">Inspección del puesto · mueve la guarnición o vuelve a tu base</div>';const skills=E.availableAbilities(s,selected),list=b.units.filter(u=>selected.includes(u.id)&&u.side==='player'&&u.hp>0&&!u.embarked),ship=list.find(u=>E.UNITS[u.type].waterborne),ground=list.some(u=>!E.UNITS[u.type].flying&&!E.UNITS[u.type].waterborne);return'<div class="skill-title">'+(b.mission?'<button data-action="mission-objectives">Objetivos</button>':'')+(list.length?'<small>'+list.length+' seleccionadas</small>':'<small>Selecciona tropas para usar habilidades</small>')+'</div><div class="skill-actions">'+skills.map(a=>'<button data-action="ability" data-type="'+a.id+'" title="'+esc(a.description)+'" '+(!a.ready?'disabled':'')+'>'+esc(a.name)+(a.ready?'':' · '+clock(a.remaining))+'</button>').join('')+(b.mission&&ground?'<button data-action="embark">Embarcar</button>':'')+(b.mission&&ship?'<button data-action="disembark" data-id="'+ship.id+'">Desembarcar</button>':'')+'</div>';}
export function eventPanel(s,h){const {esc,cost,clock}=h,e=E.initEvents(s),def=E.WORLD_EVENTS.find(v=>v.id===e.active?.id),pending=Object.values(e.pending).reduce((a,b)=>a+b,0);return'<div class="section-label">EVENTOS DE LA ISLA</div>'+(def?'<article class="quest-card"><h3>'+esc(def.name)+'</h3><p>'+esc(def.text)+'</p><small>'+clock(e.active.ends-s.time)+' para responder</small>'+cost(def.cost)+'<div class="action-row"><button data-action="event-help">'+(def.battle?'Defender la base':'Ayudar')+'</button><button data-action="event-dismiss">Dejar pasar</button></div></article>':'<p class="tiny">La próxima oportunidad aparecerá durante tus operaciones en la isla. Los eventos y sus plazos se detienen mientras estás fuera.</p>')+(pending?'<button class="wide" data-action="event-claim">Recoger '+Math.floor(pending)+' materiales reservados</button>':'')+'<div class="event-buffs">'+Object.entries(e.buffs).filter(([,end])=>end>s.time).map(([kind,end])=>'<p>'+({industry:'Industria +25%',construction:'Construcción −25% de tiempo'}[kind])+' · '+clock(end-s.time)+'</p>').join('')+'</div>';}
